def hidden_rule_fn(state):
    # Group particles by type
    brants = [p for p in state if p['type'] == 'BRANT']
    clorfs = [p for p in state if p['type'] == 'CLORF']
    vexons = [p for p in state if p['type'] == 'VEXON']

    def toroidal_delta(a, b, dim=8):
        """Compute signed toroidal delta from a to b (smallest magnitude)."""
        dx = b - a
        if dx > dim // 2:
            dx -= dim
        elif dx < -dim // 2:
            dx += dim
        return dx

    def krelon_dist(p1, p2):
        """Compute krelon_dist between two particles."""
        dx = abs(toroidal_delta(p1['x'], p2['x']))
        dy = abs(toroidal_delta(p1['y'], p2['y']))
        same_type = 0 if p1['type'] == p2['type'] else abs(dx - dy)
        return dx * dx + dy * dy + same_type

    def nearest_towards(p, targets):
        """Find nearest target and return one-step delta towards it."""
        if not targets:
            return None
        best_dist = float('inf')
        best_target = None
        for t in targets:
            d = krelon_dist(p, t)
            if d < best_dist:
                best_dist = d
                best_target = t
            elif d == best_dist and best_target is not None:
                # Tiebreaker: prefer smaller x, then smaller y
                if (t['x'], t['y']) < (best_target['x'], best_target['y']):
                    best_target = t
        if best_target is None:
            return None
        dx = toroidal_delta(p['x'], best_target['x'])
        dy = toroidal_delta(p['y'], best_target['y'])
        return (dx, dy)

    def nearest_away(p, sources):
        """Find nearest source and return one-step delta away from it."""
        if not sources:
            return None
        best_dist = float('inf')
        best_source = None
        for s in sources:
            d = krelon_dist(p, s)
            if d < best_dist:
                best_dist = d
                best_source = s
            elif d == best_dist and best_source is not None:
                if (s['x'], s['y']) < (best_source['x'], best_source['y']):
                    best_source = s
        if best_source is None:
            return None
        dx = toroidal_delta(p['x'], best_source['x'])
        dy = toroidal_delta(p['y'], best_source['y'])
        # Move away: negate the delta
        dx = -dx
        dy = -dy
        return (dx, dy)

    def apply_move(p, delta):
        if delta is None:
            return p
        dx, dy = delta
        new_x = (p['x'] + dx) % 8
        new_y = (p['y'] + dy) % 8
        return {'type': p['type'], 'x': new_x, 'y': new_y}

    result = []
    for p in state:
        if p['type'] == 'BRANT':
            # Move towards nearest CLORF
            delta = nearest_towards(p, clorfs)
            result.append(apply_move(p, delta))
        elif p['type'] == 'CLORF':
            # Move towards nearest VEXON
            delta = nearest_towards(p, vexons)
            result.append(apply_move(p, delta))
        elif p['type'] == 'VEXON':
            # Move away from nearest BRANT
            delta = nearest_away(p, brants)
            result.append(apply_move(p, delta))

    return result
